  'main.py':
    "import math\nimport random\nimport pgzrun\n\nWIDTH = 600\nHEIGHT = 800\nTITLE = 'Mergulho Alienígena'\n\nnave = Actor('nave')\ntiro = Actor('tiro')\naliens = []\nbombas = []\nceu_y = 0\nquadros = 0\nvidas = 3\npontos = 0\nvenceu = False\n\n\ndef montar_aliens():\n    aliens.clear()\n    for fila in range(2):\n        for coluna in range(8):\n            alien = Actor('alien0')\n            # Cada alien guarda as próprias informações:\n            # casa = o lugar dele na formação;\n            # estado = 'fila' (na formação), 'mergulho' (descendo), 'explodindo' ou 'fora';\n            # lado = -1 mergulha para a esquerda, 1 para a direita (metade da fila para cada lado).\n            alien.casa = (125 + coluna * 50, 160 + fila * 50)\n            alien.pos = alien.casa\n            alien.estado = 'fila'\n            alien.explosao = 0\n            if coluna < 4:\n                alien.lado = -1\n            else:\n                alien.lado = 1\n            aliens.append(alien)\n\n\ndef novo_jogo():\n    global vidas, pontos, venceu\n    vidas = 3\n    pontos = 0\n    venceu = False\n    bombas.clear()\n    montar_aliens()\n    nave.pos = (300, 720)\n    tiro.y = -20\n\n\ndef mergulhar(alien):\n    # Faz uma curva: primeiro sobe um pouco virando, depois desce rápido em direção à nave.\n    if abs(alien.angle) < 180:\n        alien.angle = alien.angle - 3 * alien.lado\n        alien.x = alien.x + 1.5 * alien.lado\n    else:\n        alien.x = alien.x + (nave.x - alien.x) * 0.01\n    if abs(alien.angle) < 90:\n        alien.y = alien.y - 1\n    else:\n        alien.y = alien.y + 4\n    if random.randint(1, 60) == 1:\n        bomba = Actor('bomba')\n        bomba.pos = alien.pos\n        bombas.append(bomba)\n    if alien.top > HEIGHT:\n        # Saiu por baixo: volta para a sua casa na formação.\n        alien.estado = 'fila'\n        alien.angle = 0\n\n\ndef acertou(alien):\n    # O alien gira no mergulho, e girar muda o tamanho do retângulo dele:\n    # por isso as batidas contam pela distância até o centro.\n    return alien.distance_to(tiro) < 20\n\n\ndef mover_aliens():\n    global pontos\n    balanco = math.sin(quadros / 90) * 60\n    for alien in aliens:\n        if alien.estado == 'fila':\n            alien.x = alien.casa[0] + balanco\n            alien.y = alien.casa[1]\n            alien.image = 'alien' + str(quadros // 15 % 2)\n            if random.randint(1, 900) == 1:\n                alien.estado = 'mergulho'\n                sounds.mergulho.play()\n        elif alien.estado == 'mergulho':\n            mergulhar(alien)\n        elif alien.estado == 'explodindo':\n            # Três desenhos de explosão, seis quadros cada.\n            alien.image = 'explosao' + str(alien.explosao // 6 + 1)\n            alien.explosao = alien.explosao + 1\n            if alien.explosao == 18:\n                alien.estado = 'fora'\n                # Fora do jogo: o alien vai para longe da tela.\n                alien.pos = (-100, -100)\n        if alien.estado in ('fila', 'mergulho'):\n            if acertou(alien):\n                alien.estado = 'explodindo'\n                alien.angle = 0\n                tiro.y = -20\n                pontos = pontos + 50\n                sounds.acerto.play()\n            elif alien.distance_to(nave) < 34:\n                alien.estado = 'explodindo'\n                alien.angle = 0\n                perder_vida()\n\n\ndef sobrou_algum():\n    for alien in aliens:\n        if alien.estado in ('fila', 'mergulho'):\n            return True\n    return False\n\n\ndef perder_vida():\n    global vidas\n    if vidas > 0:\n        vidas = vidas - 1\n        sounds.dano.play()\n    # As bombas que estavam caindo somem: a nave ganha um respiro.\n    bombas.clear()\n\n\ndef draw():\n    screen.blit('fundo', (0, 0))\n    screen.blit('estrelas', (0, ceu_y))\n    screen.blit('estrelas', (0, ceu_y - HEIGHT))\n    for alien in aliens:\n        alien.draw()\n    for bomba in bombas:\n        bomba.draw()\n    tiro.draw()\n    if vidas > 0:\n        nave.draw()\n    screen.draw.text('Pontos: ' + str(pontos), topleft=(12, 8), fontsize=30, color='white')\n    screen.draw.text('Vidas: ' + str(vidas), topright=(WIDTH - 12, 8), fontsize=30, color='white')\n    if venceu:\n        screen.draw.text('Você venceu a esquadra!', center=(WIDTH / 2, 380), fontsize=48, color='yellow')\n    elif vidas == 0:\n        screen.draw.text('Fim de jogo!', center=(WIDTH / 2, 380), fontsize=60, color='orange')\n    if venceu or vidas == 0:\n        screen.draw.text('Espaço recomeça', center=(WIDTH / 2, 430), fontsize=36, color='white')\n\n\ndef update():\n    global ceu_y, quadros, venceu\n    quadros = quadros + 1\n    ceu_y = (ceu_y + 0.5) % HEIGHT\n    if vidas == 0 or venceu:\n        return\n    if keyboard.left and nave.left > 0:\n        nave.x = nave.x - 5\n    if keyboard.right and nave.right < WIDTH:\n        nave.x = nave.x + 5\n    if tiro.y > -20:\n        tiro.y = tiro.y - 10\n    mover_aliens()\n    for bomba in list(bombas):\n        bomba.y = bomba.y + 5\n        if bomba.top > HEIGHT:\n            bombas.remove(bomba)\n        elif bomba.colliderect(nave):\n            # perder_vida esvazia a lista de bombas: não há mais nenhuma para olhar.\n            perder_vida()\n            break\n    if not sobrou_algum():\n        venceu = True\n        sounds.vitoria.play()\n\n\ndef on_key_down(key):\n    if key != keys.SPACE:\n        return\n    if vidas == 0 or venceu:\n        novo_jogo()\n    elif tiro.y <= -20:\n        tiro.midbottom = nave.midtop\n        sounds.tiro.play()\n\n\nnovo_jogo()\npgzrun.go()\n",
  'README.md':
    '# Mergulho Alienígena\n\nA esquadra balança no céu e, de repente, um alien sai da fila e mergulha em curva.\n\nUm exemplo original feito com [Pygame Zero](https://pygame-zero.readthedocs.io/): o\nprograma inteiro está em `main.py` e é o mesmo nas versões de Blocos e de Código da\ngaleria.\n\n## Como jogar\n\nMova a nave com as setas e atire com espaço. Acerte os aliens na fila ou no meio do mergulho e desvie das bombas.\n\n## Ideias para mudar\n\n- Faça os aliens mergulharem mais vezes.\n- Mude a curva do mergulho trocando os números do ângulo.\n- Dê mais pontos para quem acerta um alien mergulhando.\n\n## Imagens e sons\n\nO Pygame Zero procura as imagens em `images/`, os sons em `sounds/` e as músicas em\n`music/`, pelo nome do arquivo sem a extensão: `Actor(\'nave\')` usa `images/nave`.\nPara trocar um desenho, edite-o no Pinta pelo Estúdio, ou traga outro e use no código o\nnome que o painel mostra em "nome no código".\n\n## Jogar no computador\n\nO Pygame Zero roda no computador com o pygame-ce:\n\n```\npython -m pip install pygame-ce==2.5.8 numpy\npython -m pip install --no-deps pgzero==1.2.1\npython main.py\n```\n\nO programa termina com `pgzrun.go()`, então `python main.py` já abre o jogo. Num programa\nsem essa linha, use `python -X utf8 -m pgzero main.py` (o `-X utf8` mantém os acentos\ncertos no Windows).\n\nAo baixar o projeto pelo Estúdio, os desenhos em SVG ganham uma cópia em PNG, que é o\nformato que o Pygame Zero do computador abre.\n',
